#!/usr/bin/env bash
# Store or restore the node_modules cache on Linux / macOS.
#
# Usage:
#   cache.sh archive   # create  .build/node_modules_cache/node-modules-<part>.tzst (cache miss)
#   cache.sh extract   # restore .build/node_modules_cache/node-modules*.tzst (cache hit)
#
# Splits node_modules into parts (see splitList.ts) that are archived and extracted in
# parallel: one tar process extracts them about twice as slowly as several. Uses
# multi-threaded zstd. The archives must NOT be named cache.tzst because actions/cache
# reserves that name and excludes it from the saved cache. Extract also restores the
# single node-modules.tzst of the caches saved before the parts. The archive and
# extract flags must stay compatible; if you change the format here, bump
# build/.cachesalt to invalidate old caches.
set -e

PARTS=8

# Runs the given command once for each of the remaining arguments, in parallel, and fails
# when any of them fails.
parallel() {
	local command=$1
	shift
	local pids=()
	for argument in "$@"; do
		$command "$argument" &
		pids+=($!)
	done
	local failed=0
	for pid in "${pids[@]}"; do
		wait "$pid" || failed=1
	done
	return $failed
}

archive_part() {
	tar --use-compress-program='zstd -T0 -3' -cf ".build/node_modules_cache/node-modules-${1##*.}.tzst" --files-from "$1"
}

extract_part() {
	tar --use-compress-program='zstd -d -T0' -xf "$1"
}

case "$1" in
	archive)
		rm -f .build/node_modules_list.txt.*
		node build/azure-pipelines/common/listNodeModules.ts .build/node_modules_list.txt
		node .github/workflows/node_modules_cache/splitList.ts .build/node_modules_list.txt $PARTS
		mkdir -p .build/node_modules_cache
		rm -f .build/node_modules_cache/node-modules*.tzst
		parallel archive_part .build/node_modules_list.txt.*
		;;
	extract)
		parallel extract_part .build/node_modules_cache/node-modules*.tzst
		;;
	*)
		echo "Usage: $0 {archive|extract}" >&2
		exit 1
		;;
esac
